  "prediction_basis_card_ids": ["C07", "C14", "C03", "C06", "C12", "C28", "C50", "C51"],
  "claims": [
    {
      "claim": "Meperidine and encainide, the closest measured piperidine/opioid contexts, show F = 0.80 and 76–78% in cirrhosis (C07/C14, C03/C06/C12); L2 indicates cirrhosis raises meperidine availability by 81% (C17) and encainide availability >2-fold versus healthy extensive metabolizers (C21), so normal-condition estimates remain above the 20% threshold.",
      "card_ids": ["C07", "C14", "C17", "C03", "C06", "C12", "C21"]
    },
    {
      "claim": "Oral exposure and permeability records support the absorption component: fentanyl shows measurable oral plasma exposure (C28), and basic piperidines show high Papp with no meaningful efflux (C50, C51).",
      "card_ids": ["C28", "C50", "C51"]
    },
    {
      "claim": "L6 shows fentanyl/sufentanil are CYP3A4 substrates with high hepatic extraction (C61, C65) and carfentanil has a very short HLM half-life (C66, C70, C71); this is mechanistic presystemic loss, but no card provides a direct sufentanil F value or an affirmative F < 20% outcome.",
      "card_ids": ["C61", "C65", "C66", "C70", "C71"]
    },
    {
      "claim": "Meptazinol L2 implies normal F ~7% (four-fold lower than the 27.9% cirrhosis value), but its phenol-azepine scaffold is structurally distant from the 4-anilidopiperidine query, so this negative context carries low transfer weight.",
      "card_ids": ["C04", "C19", "C24"]
    },
    {
      "claim": "No affirmative threshold-relevant evidence supports F < 20%; P-gp substrate status (C53/C59) and high first-pass metabolism are caveats, not low-F verdicts.",
      "card_ids": ["C53", "C59", "C56", "C61", "C65"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "weakened",
      "card_ids": ["C61", "C62", "C65", "C66", "C68", "C70", "C71", "C72"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for sufentanil (the query) in any supplied record.",
    "L6 hepatic-clearance records are mostly for fentanyl/carfentanil; only C61 names sufentanil, and no sufentanil-specific clearance or F value is provided.",
    "Closest high-F contexts (meperidine, encainide) were measured in cirrhosis; normal-condition F is inferred with uncertainty.",
    "Meptazinol context implies low normal F (~7%) but structural transfer to the 4-anilidopiperidine query is limited.",
    "No query-specific solubility, intestinal metabolism, or formulation data are available."
  ],
  "decision_summary": "Prediction remains high: sufentanil has favorable absorption and the closest piperidine/opioid contexts support F > 20%; L6 hepatic-clearance evidence adds a first-pass caveat but does not provide an affirmative F < 20% result. Confidence is lowered to low because no direct sufentanil F measurement is available and first-pass metabolism is substantial."
}

